@startuml

class Library {
  + code : string
}

class User {
  + name : string
  + phone : string
  + email : string
  + mail : string
  + securityDeposit : float
}

class BorrowableItem {
  + libraryCode : string
  + location : string
}

class Book extends BorrowableItem {
  + publisher : string
}

class Author {
  + name : string
}

class MagazineIssue extends BorrowableItem {
  + publicationDate : date
  + publisher : string
}

class MusicCD extends BorrowableItem {
  + publisher : string
  + artist : string
}

class Film extends BorrowableItem {
  + duration : int
  + publisher : string
}

class Actor {
  + name : string
}

class DVDFilm extends Film {}

class VHSFilm extends Film {}

class Loan {
  + dueDate : date
}

Library "1" -- "*" User : has
Library "1" -- "*" BorrowableItem : has
User "1" -- "0..3" Loan : makes
Loan "1" -- "1" BorrowableItem : involves
Book "*" -- "1..*" Author : writtenBy

Film "*" -- "1..*" Actor : features
Book "*" -- "1" Library : belongsTo
MagazineIssue "*" -- "1" Library : belongsTo
MusicCD "*" -- "1" Library : belongsTo
DVDFilm "*" -- "1" Library : belongsTo
VHSFilm "*" -- "1" Library : belongsTo

@enduml

